import { expect, test } from "@playwright/test";
import { fileURLToPath } from "node:url";

/**
 * Statement import with a synthetic Santander checking export (generated by backend/tests/statement_samples.py,
 * santander_xlsx). Never a real cartola: the repository is public. With durable storage a second run finds the
 * statement already imported, so both outcomes are accepted.
 */
const SAMPLE = fileURLToPath(new URL("./fixtures/synthetic-santander.xlsx", import.meta.url));

test.describe("Statements", () => {
  test("import a synthetic statement, read it back and see its transactions", async ({ page }) => {
    await page.goto("/statements");
    await expect(page.getByText(/Projections, the purchase check and the savings plan still use the demo scenario/)).toBeVisible();

    await page.getByLabel("Choose file").setInputFiles(SAMPLE);
    const result = page.getByRole("heading", { name: "Imported synthetic-santander.xlsx" });
    await expect(result).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(/transactions in the ledger/)).toBeVisible();

    // The list: masked account, currency code on the balance, verified.
    await page.getByRole("button", { name: /Open statement for \*\*\*\*3456/ }).click();
    await expect(page.getByRole("heading", { level: 2, name: /\*\*\*\*3456/ })).toBeVisible();
    // The holder's name and the transfer reference were removed at import and show as chips.
    await expect(page.locator("[data-placeholder='PERSON']").first()).toBeVisible();
    await expect(page.getByText("[PERSON]")).toHaveCount(0);

    await page.getByRole("radio", { name: "Transactions" }).check({ force: true });
    const table = page.getByRole("table", { name: "Transactions from imported statements" });
    await expect(table).toContainText("CLP −900");
    await expect(table).toContainText("CLP 26,000");
  });

  test("the other persona sees none of it", async ({ page }) => {
    await page.goto("/statements");
    await page.getByRole("radio", { name: /Diego/ }).check({ force: true });
    await expect(page.getByRole("button", { name: /Open statement for \*\*\*\*3456/ })).toHaveCount(0);
  });
});
